export default function booleanCheck(operation, booleans) {
  return booleans.reduce((a, b) => {
    if (a === "start") {
      return b;
    }
    if (operation === "or") {
      return a || b;
    }
    return a && b;
  }, "start");
}
flarum.reg.add('fof-linguist', 'admin/utils/booleanCheck', booleanCheck);